private async enqueueChunk(chunkEvent: MatrixEvent): Promise<void> {
    const eventId = chunkEvent.getId();

    if (!eventId) {
        logger.warn("got voice broadcast chunk event without ID", this.infoEvent, chunkEvent);
        return;
    }

    if (this.playbacks.has(eventId)) return;

    const pending = this.pendingPlaybacks.get(eventId);
    if (pending) return pending;

    const promise = this.loadChunkPlayback(chunkEvent, eventId);
    this.pendingPlaybacks.set(eventId, promise);

    try {
        await promise;
    } finally {
        if (this.pendingPlaybacks.get(eventId) === promise) {
            this.pendingPlaybacks.delete(eventId);
        }
    }
